//! SRTP encrypt / decrypt — AES-CM-128-HMAC-SHA1-80.
//!
//! RFC 3711 §3: an SRTP packet is:
//!   [RTP header][encrypted payload][HMAC-SHA1-80 tag (10 bytes)]
//!
//! Encryption: AES Counter Mode (AES-CM). The keystream is generated by
//! encrypting the IV with AES-CM, then XOR'd with the plaintext payload.
//!
//! Authentication: HMAC-SHA1 over [RTP header || encrypted payload].
//! We use an 80-bit (10-byte) truncation of the 20-byte HMAC-SHA1 output.
//! The tag is appended after the payload, not included in the encrypted region.
//!
//! IV for AES-CM (RFC 3711 §4.1):
//!   IV = (k_s XOR (SSRC << 64) XOR (index << 16)) as 128-bit big-endian
//! where index = 2^16 × ROC + SEQ (ROC = rollover counter, SEQ = sequence num).

use super::key_mgmt::SrtpSessionKeys;

// HMAC-SHA1 is different from SHA-256 but shares the same structural pattern.
// Rather than import an external crate, we implement HMAC-SHA1 directly
// from RFC 2104 using the SHA-1 implementation below.
// Phase 4 replaces this with ring::hmac.

use crate::rtp::session::RTP_HEADER_LEN;

// ─── SRTP packet index ─────────────────────────────────────────

/// Compute the SRTP packet index from sequence number and rollover counter.
/// index = 2^16 × ROC + SEQ (RFC 3711 §3.3.1).
pub fn srtp_index(seq: u16, roc: u32) -> u64 {
    ((roc as u64) << 16) | (seq as u16 as u64)
}

// ─── AES-CM keystream ──────────────────────────────────────────

/// Build the AES-CM IV for a given packet.
/// IV = k_s XOR (SSRC << 64) XOR (index << 16) — all as 128-bit BE.
fn build_iv(k_s: &[u8], ssrc: u32, index: u64) -> [u8; 16] {
    let mut iv = [0u8; 16];
    // Embed session salt (14 bytes at offset 2).
    let salt_len = k_s.len().min(14);
    iv[2..2 + salt_len].copy_from_slice(&k_s[..salt_len]);
    // XOR SSRC into bytes 4..8 (bits [95:64]).
    let ssrc_bytes = ssrc.to_be_bytes();
    for i in 0..4 { iv[4 + i] ^= ssrc_bytes[i]; }
    // XOR (index << 16) into bytes 8..14 (bits [63:16]).
    let idx_bytes = (index << 16).to_be_bytes(); // u64 BE
    for i in 0..8 { iv[8 + i] ^= idx_bytes[i]; }
    iv
}

/// Generate AES-CM keystream using our pure-Rust AES-128 from key_mgmt.
/// (Re-uses the same CTR function through the public PRF path.)
fn aes_cm_keystream(k_e: &[u8], iv: &[u8; 16], length: usize) -> Vec<u8> {
        // We call the AES-128-CTR primitive directly via a local re-implementation
    // rather than re-exporting the private function from key_mgmt.
    // Phase 4: replace with ring::aead::AES_128_GCM.
    aes128_ctr(k_e, iv, length)
}

fn aes128_ctr(key: &[u8], iv: &[u8; 16], length: usize) -> Vec<u8> {
    // Identical to key_mgmt::aes128_ctr_keystream — duplicated here so
    // srtp/encrypt.rs has no dependency on key_mgmt internals.
    let mut out = Vec::with_capacity(length);
    let mut ctr  = u128::from_be_bytes(*iv);
    let rk       = aes128_key_expand_local(key);
    while out.len() < length {
        let block = aes128_encrypt_local(&rk, &ctr.to_be_bytes());
        let take  = (length - out.len()).min(16);
        out.extend_from_slice(&block[..take]);
        ctr = ctr.wrapping_add(1);
    }
    out
}

// ─── Encrypt ───────────────────────────────────────────────────

/// Encrypt an RTP packet to produce an SRTP packet.
///
/// Takes a complete RTP packet (header + plaintext payload).
/// Returns: [original RTP header][encrypted payload][10-byte HMAC-SHA1 tag]
pub fn srtp_encrypt(
    rtp_packet: &[u8],
    keys:        &SrtpSessionKeys,
    ssrc:        u32,
    seq:         u16,
    roc:         u32,
) -> Vec<u8> {
    if rtp_packet.len() < RTP_HEADER_LEN {
        return rtp_packet.to_vec();
    }
    let header  = &rtp_packet[..RTP_HEADER_LEN];
    let payload = &rtp_packet[RTP_HEADER_LEN..];

    // 1. Generate keystream for the payload length.
    let index  = srtp_index(seq, roc);
    let iv     = build_iv(&keys.k_s, ssrc, index);
    let stream = aes_cm_keystream(&keys.k_e, &iv, payload.len());

    // 2. XOR plaintext with keystream → ciphertext.
    let ciphertext: Vec<u8> = payload.iter().zip(stream.iter())
        .map(|(&p, &k)| p ^ k).collect();

    // 3. Build the authenticated region: header || ciphertext.
    let mut auth_data = Vec::with_capacity(header.len() + ciphertext.len());
    auth_data.extend_from_slice(header);
    auth_data.extend_from_slice(&ciphertext);

    // 4. Compute HMAC-SHA1-80 over auth_data.
    let tag = hmac_sha1_80(&keys.k_a, &auth_data);

    // 5. Assemble: header || ciphertext || tag.
    let mut out = auth_data;
    out.extend_from_slice(&tag);
    out
}

// ─── Decrypt ───────────────────────────────────────────────────

/// Decrypt an SRTP packet to produce a plain RTP packet.
///
/// Takes a complete SRTP packet (header + ciphertext + 10-byte tag).
/// Returns `None` if the tag is wrong (authentication failure).
pub fn srtp_decrypt(
    srtp_packet: &[u8],
    keys:         &SrtpSessionKeys,
    ssrc:         u32,
    seq:          u16,
    roc:          u32,
) -> Option<Vec<u8>> {
    const TAG_LEN: usize = 10;
    if srtp_packet.len() < RTP_HEADER_LEN + TAG_LEN {
        return None;
    }

    let header_end    = RTP_HEADER_LEN;
    let tag_start     = srtp_packet.len() - TAG_LEN;
    let header        = &srtp_packet[..header_end];
    let ciphertext    = &srtp_packet[header_end..tag_start];
    let received_tag  = &srtp_packet[tag_start..];

    // 1. Verify HMAC-SHA1-80 before doing any decryption.
    let mut auth_data = Vec::with_capacity(header.len() + ciphertext.len());
    auth_data.extend_from_slice(header);
    auth_data.extend_from_slice(ciphertext);
    let expected_tag = hmac_sha1_80(&keys.k_a, &auth_data);

    if !constant_time_eq(&expected_tag, received_tag) {
        return None; // Authentication failure — drop packet.
    }

    // 2. Generate keystream and XOR to recover plaintext.
    let index  = srtp_index(seq, roc);
    let iv     = build_iv(&keys.k_s, ssrc, index);
    let stream = aes_cm_keystream(&keys.k_e, &iv, ciphertext.len());

    let plaintext: Vec<u8> = ciphertext.iter().zip(stream.iter())
        .map(|(&c, &k)| c ^ k).collect();

    // 3. Reassemble: header || plaintext.
    let mut out = Vec::with_capacity(header.len() + plaintext.len());
    out.extend_from_slice(header);
    out.extend_from_slice(&plaintext);
    Some(out)
}

// ─── HMAC-SHA1-80 ──────────────────────────────────────────────

/// HMAC-SHA1 with 80-bit (10-byte) output truncation (RFC 3711 §4.2.1).
fn hmac_sha1_80(key: &[u8], data: &[u8]) -> [u8; 10] {
    let full = hmac_sha1(key, data);
    let mut out = [0u8; 10];
    out.copy_from_slice(&full[..10]);
    out
}

/// HMAC-SHA1 (RFC 2104). Output is 20 bytes.
fn hmac_sha1(key: &[u8], data: &[u8]) -> [u8; 20] {
    const BLOCK: usize = 64;
    // Key normalisation: hash if longer than block size, zero-pad otherwise.
    let mut k = [0u8; BLOCK];
    if key.len() > BLOCK {
        let h = sha1(key);
        k[..20].copy_from_slice(&h);
    } else {
        k[..key.len()].copy_from_slice(key);
    }
    // ipad and opad.
    let mut ikey = [0u8; BLOCK]; let mut okey = [0u8; BLOCK];
    for i in 0..BLOCK {
        ikey[i] = k[i] ^ 0x36;
        okey[i] = k[i] ^ 0x5c;
    }
    // inner = SHA1(ipad || data)
    let mut inner_input = Vec::with_capacity(BLOCK + data.len());
    inner_input.extend_from_slice(&ikey);
    inner_input.extend_from_slice(data);
    let inner = sha1(&inner_input);
    // outer = SHA1(opad || inner)
    let mut outer_input = Vec::with_capacity(BLOCK + 20);
    outer_input.extend_from_slice(&okey);
    outer_input.extend_from_slice(&inner);
    sha1(&outer_input)
}

// ─── SHA-1 ─────────────────────────────────────────────────────
// FIPS 180-4 SHA-1. Used only for HMAC-SHA1 in SRTP authentication.
// Phase 4: replaced by ring::hmac::HMAC_SHA1_FOR_LEGACY_USE_ONLY.

fn sha1(msg: &[u8]) -> [u8; 20] {
    let mut h: [u32; 5] = [0x67452301,0xEFCDAB89,0x98BADCFE,0x10325476,0xC3D2E1F0];
    let bit_len = (msg.len() as u64) * 8;
    let mut padded = msg.to_vec();
    padded.push(0x80);
    while padded.len() % 64 != 56 { padded.push(0); }
    padded.extend_from_slice(&bit_len.to_be_bytes());

    for chunk in padded.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes(chunk[i*4..i*4+4].try_into().unwrap());
        }
        for i in 16..80 {
            w[i] = (w[i-3]^w[i-8]^w[i-14]^w[i-16]).rotate_left(1);
        }
        let (mut a,mut b,mut c,mut d,mut e) = (h[0],h[1],h[2],h[3],h[4]);
        for i in 0..80 {
            let (f, k) = match i {
                0..=19  => ((b&c)|((!b)&d),            0x5A827999u32),
                20..=39 => (b^c^d,                     0x6ED9EBA1u32),
                40..=59 => ((b&c)|(b&d)|(c&d),         0x8F1BBCDCu32),
                _       => (b^c^d,                     0xCA62C1D6u32),
            };
            let temp = a.rotate_left(5).wrapping_add(f).wrapping_add(e)
                        .wrapping_add(k).wrapping_add(w[i]);
            e=d; d=c; c=b.rotate_left(30); b=a; a=temp;
        }
        h[0]=h[0].wrapping_add(a); h[1]=h[1].wrapping_add(b);
        h[2]=h[2].wrapping_add(c); h[3]=h[3].wrapping_add(d);
        h[4]=h[4].wrapping_add(e);
    }
    let mut out = [0u8; 20];
    for (i, &word) in h.iter().enumerate() {
        out[i*4..i*4+4].copy_from_slice(&word.to_be_bytes());
    }
    out
}

// ─── Constant-time comparison ──────────────────────────────────

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() { return false; }
    a.iter().zip(b.iter()).fold(0u8, |acc, (&x, &y)| acc | (x ^ y)) == 0
}

// ─── AES-128 (local copy for encrypt.rs independence) ─────────

const SBOX: [u8; 256] = [
    0x63,0x7c,0x77,0x7b,0xf2,0x6b,0x6f,0xc5,0x30,0x01,0x67,0x2b,0xfe,0xd7,0xab,0x76,
    0xca,0x82,0xc9,0x7d,0xfa,0x59,0x47,0xf0,0xad,0xd4,0xa2,0xaf,0x9c,0xa4,0x72,0xc0,
    0xb7,0xfd,0x93,0x26,0x36,0x3f,0xf7,0xcc,0x34,0xa5,0xe5,0xf1,0x71,0xd8,0x31,0x15,
    0x04,0xc7,0x23,0xc3,0x18,0x96,0x05,0x9a,0x07,0x12,0x80,0xe2,0xeb,0x27,0xb2,0x75,
    0x09,0x83,0x2c,0x1a,0x1b,0x6e,0x5a,0xa0,0x52,0x3b,0xd6,0xb3,0x29,0xe3,0x2f,0x84,
    0x53,0xd1,0x00,0xed,0x20,0xfc,0xb1,0x5b,0x6a,0xcb,0xbe,0x39,0x4a,0x4c,0x58,0xcf,
    0xd0,0xef,0xaa,0xfb,0x43,0x4d,0x33,0x85,0x45,0xf9,0x02,0x7f,0x50,0x3c,0x9f,0xa8,
    0x51,0xa3,0x40,0x8f,0x92,0x9d,0x38,0xf5,0xbc,0xb6,0xda,0x21,0x10,0xff,0xf3,0xd2,
    0xcd,0x0c,0x13,0xec,0x5f,0x97,0x44,0x17,0xc4,0xa7,0x7e,0x3d,0x64,0x5d,0x19,0x73,
    0x60,0x81,0x4f,0xdc,0x22,0x2a,0x90,0x88,0x46,0xee,0xb8,0x14,0xde,0x5e,0x0b,0xdb,
    0xe0,0x32,0x3a,0x0a,0x49,0x06,0x24,0x5c,0xc2,0xd3,0xac,0x62,0x91,0x95,0xe4,0x79,
    0xe7,0xc8,0x37,0x6d,0x8d,0xd5,0x4e,0xa9,0x6c,0x56,0xf4,0xea,0x65,0x7a,0xae,0x08,
    0xba,0x78,0x25,0x2e,0x1c,0xa6,0xb4,0xc6,0xe8,0xdd,0x74,0x1f,0x4b,0xbd,0x8b,0x8a,
    0x70,0x3e,0xb5,0x66,0x48,0x03,0xf6,0x0e,0x61,0x35,0x57,0xb9,0x86,0xc1,0x1d,0x9e,
    0xe1,0xf8,0x98,0x11,0x69,0xd9,0x8e,0x94,0x9b,0x1e,0x87,0xe9,0xce,0x55,0x28,0xdf,
    0x8c,0xa1,0x89,0x0d,0xbf,0xe6,0x42,0x68,0x41,0x99,0x2d,0x0f,0xb0,0x54,0xbb,0x16,
];
const RCON: [u8;11] = [0x00,0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1b,0x36];

fn aes128_key_expand_local(key: &[u8]) -> [[u8;16];11] {
    let mut rk = [[0u8;16];11];
    rk[0][..].copy_from_slice(&key[..16]);
    for i in 1..=10 {
        let prev = rk[i-1];
        let w = [
            SBOX[prev[13] as usize]^RCON[i],
            SBOX[prev[14] as usize],
            SBOX[prev[15] as usize],
            SBOX[prev[12] as usize],
        ];
        for j in 0..4 {
            let (c0,c1,c2,c3) = if j==0 { (w[0],w[1],w[2],w[3]) }
                else { let b=(j-1)*4; (rk[i][b],rk[i][b+1],rk[i][b+2],rk[i][b+3]) };
            rk[i][j*4]   = prev[j*4]   ^ c0;
            rk[i][j*4+1] = prev[j*4+1] ^ c1;
            rk[i][j*4+2] = prev[j*4+2] ^ c2;
            rk[i][j*4+3] = prev[j*4+3] ^ c3;
        }
    }
    rk
}

fn aes128_encrypt_local(rk: &[[u8;16];11], block: &[u8]) -> [u8;16] {
    let mut s: [u8;16] = block.try_into().unwrap();
    for i in 0..16 { s[i] ^= rk[0][i]; }
    for r in 1..10 {
        for b in s.iter_mut() { *b = SBOX[*b as usize]; }
        let t=s[1]; s[1]=s[5]; s[5]=s[9]; s[9]=s[13]; s[13]=t;
        s.swap(2,10); s.swap(6,14);
        let t=s[15]; s[15]=s[11]; s[11]=s[7]; s[7]=s[3]; s[3]=t;
        for c in 0..4 {
            let i=c*4;
            let (s0,s1,s2,s3)=(s[i],s[i+1],s[i+2],s[i+3]);
            let x=|b:u8| if b&0x80!=0 {(b<<1)^0x1b} else {b<<1};
            s[i]   = x(s0)^x(s1)^s1^s2^s3;
            s[i+1] = s0^x(s1)^x(s2)^s2^s3;
            s[i+2] = s0^s1^x(s2)^x(s3)^s3;
            s[i+3] = x(s0)^s0^s1^s2^x(s3);
        }
        for i in 0..16 { s[i] ^= rk[r][i]; }
    }
    for b in s.iter_mut() { *b = SBOX[*b as usize]; }
    let t=s[1]; s[1]=s[5]; s[5]=s[9]; s[9]=s[13]; s[13]=t;
    s.swap(2,10); s.swap(6,14);
    let t=s[15]; s[15]=s[11]; s[11]=s[7]; s[7]=s[3]; s[3]=t;
    for i in 0..16 { s[i] ^= rk[10][i]; }
    s
}
